# Terraform Dev/Prod Refactor to `for_each` Module

## Strategy: Zero-Diff State Migration

The goal is to consolidate duplicated resource blocks into a single parameterized module, using `terraform state mv` to prevent resource churn.

---

## Phase 1: Create the Module Structure

### Before (current structure)
```
.
├── main.tf                    # contains aws_eks_cluster.dev, aws_eks_cluster.prod, etc.
├── variables.tf
├── dev.tfvars
└── prod.tfvars
```

### After (target structure)
```
.
├── modules/
│   └── app/
│       ├── main.tf            # all resources parameterized
│       ├── variables.tf
│       └── outputs.tf
├── main.tf                    # calls module.app[env]
├── variables.tf               # env-level variables
├── dev.tfvars
└── prod.tfvars
```

---

## Phase 2: Extract into Module

### `modules/app/variables.tf`

```hcl
variable "environment" {
  type = string
}

variable "aws_region" {
  type = string
}

variable "eks_node_count" {
  type = number
}

variable "eks_instance_type" {
  type = string
}

variable "rds_instance_class" {
  type = string
}

variable "rds_multi_az" {
  type = bool
  default = false
}

variable "s3_replication_enabled" {
  type = bool
  default = false
}

variable "s3_replication_destination_region" {
  type = string
  default = null
}

variable "iam_oidc_enabled" {
  type = bool
  default = false
}

variable "oidc_provider_arn" {
  type = string
  default = null
}

# Common tags
variable "tags" {
  type = map(string)
}
```

### `modules/app/main.tf`

```hcl
locals {
  env = var.environment
}

# EKS Cluster
resource "aws_eks_cluster" "app" {
  name            = "app-${local.env}"
  role_arn        = aws_iam_role.eks_cluster.arn
  version         = "1.28"

  vpc_config {
    subnet_ids = data.aws_subnets.private.ids
  }

  tags = merge(var.tags, { Environment = local.env })
}

resource "aws_eks_node_group" "app" {
  cluster_name    = aws_eks_cluster.app.name
  node_group_name = "app-${local.env}"
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = data.aws_subnets.private.ids

  scaling_config {
    desired_size = var.eks_node_count
    max_size     = var.eks_node_count + 1
    min_size     = var.eks_node_count
  }

  instance_types = [var.eks_instance_type]

  tags = merge(var.tags, { Environment = local.env })
}

# S3 Bucket
resource "aws_s3_bucket" "app_assets" {
  bucket = "app-assets-${local.env}-${data.aws_caller_identity.current.account_id}"
  tags   = merge(var.tags, { Environment = local.env })
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Replication (prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count = var.s3_replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.app_assets.id
  role   = aws_iam_role.s3_replication[0].arn

  rule {
    status = "Enabled"

    destination {
      bucket       = "arn:aws:s3:::app-assets-${local.env}-replica-${data.aws_caller_identity.current.account_id}"
      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
      storage_class = "STANDARD_IA"
    }

    filter {}
  }

  depends_on = [aws_s3_bucket_versioning.app_assets]
}

# RDS PostgreSQL
resource "aws_db_instance" "app" {
  identifier           = "app-${local.env}"
  engine               = "postgres"
  engine_version       = "15.3"
  instance_class       = var.rds_instance_class
  allocated_storage    = 20
  storage_encrypted    = true
  multi_az             = var.rds_multi_az
  publicly_accessible  = false

  db_name  = "appdb"
  username = "appuser"
  password = random_password.db_password.result

  backup_retention_period = 7
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "app-${local.env}-final-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  db_subnet_group_name   = aws_db_subnet_group.app.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = merge(var.tags, { Environment = local.env })
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_password" {
  name = "app/${local.env}/db-password"
  tags = merge(var.tags, { Environment = local.env })
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id = aws_secretsmanager_secret.db_password.id
  secret_string = jsonencode({
    username = aws_db_instance.app.username
    password = random_password.db_password.result
    host     = aws_db_instance.app.address
    port     = aws_db_instance.app.port
    dbname   = aws_db_instance.app.db_name
  })
}

# IAM Service Account Role
resource "aws_iam_role" "app_service" {
  name = "app-service-${local.env}"

  assume_role_policy = var.iam_oidc_enabled ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:sub" = "system:serviceaccount:default:app-service"
          }
        }
      }
    ]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.app_service[0].arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Environment = local.env })
}

resource "aws_iam_role_policy" "app_service" {
  name = "app-service-policy"
  role = aws_iam_role.app_service.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect   = "Allow"
          Action   = ["s3:GetObject", "s3:PutObject"]
          Resource = "${aws_s3_bucket.app_assets.arn}/*"
        },
        {
          Effect   = "Allow"
          Action   = ["s3:ListBucket"]
          Resource = aws_s3_bucket.app_assets.arn
        }
      ],
      local.env == "prod" ? [
        {
          Effect = "Allow"
          Action = [
            "secretsmanager:GetSecretValue"
          ]
          Resource = aws_secretsmanager_secret.db_password.arn
        }
      ] : []
    )
  })
}

# IAM User (dev only, for programmatic access)
resource "aws_iam_user" "app_service" {
  count = local.env == "dev" ? 1 : 0
  name  = "app-service-${local.env}"
  tags  = merge(var.tags, { Environment = local.env })
}

resource "aws_iam_access_key" "app_service" {
  count       = local.env == "dev" ? 1 : 0
  user        = aws_iam_user.app_service[0].name
  depends_on  = [aws_iam_user.app_service]
}

# ALB / CloudFront
resource "aws_lb" "app_internal" {
  count              = local.env == "dev" ? 1 : 0
  name               = "app-internal-${local.env}"
  internal           = true
  load_balancer_type = "application"
  subnets            = data.aws_subnets.private.ids
  tags               = merge(var.tags, { Environment = local.env })
}

resource "aws_lb_listener" "app_internal" {
  count              = local.env == "dev" ? 1 : 0
  load_balancer_arn  = aws_lb.app_internal[0].arn
  port               = 443
  protocol           = "HTTPS"
  ssl_policy         = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn    = aws_acm_certificate.app_internal[0].arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[count.index].arn
  }
}

resource "aws_cloudfront_distribution" "app" {
  count   = local.env == "prod" ? 1 : 0
  enabled = true

  origin {
    domain_name = aws_lb.app_internal[0].dns_name
    origin_id   = "alb"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "alb"

    forwarded_values {
      query_string = true
      cookies {
        forward = "all"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.app_prod[0].arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  tags = merge(var.tags, { Environment = local.env })
}

# Supporting data/resources
data "aws_caller_identity" "current" {}

resource "aws_db_subnet_group" "app" {
  name       = "app-${local.env}"
  subnet_ids = data.aws_subnets.private.ids
}

resource "aws_security_group" "rds" {
  name        = "app-rds-${local.env}"
  description = "RDS security group for app ${local.env}"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "app" {
  name        = "app-${local.env}"
  description = "App security group for ${local.env}"
  vpc_id      = data.aws_vpc.default.id
}

# Fetch existing VPC/subnet data
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "private" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
  tags = {
    Tier = "Private"
  }
}

# IAM Roles for EKS (simplified)
resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster-${local.env}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role" "eks_node" {
  name = "eks-node-${local.env}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role" "s3_replication" {
  count = var.s3_replication_enabled ? 1 : 0
  name  = "s3-replication-${local.env}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count = var.s3_replication_enabled ? 1 : 0
  name  = "s3-replication-policy"
  role  = aws_iam_role.s3_replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.app_assets.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.app_assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "arn:aws:s3:::app-assets-${local.env}-replica-${data.aws_caller_identity.current.account_id}/*"
      }
    ]
  })
}

# ACM Certificates (simplified)
resource "aws_acm_certificate" "app_internal" {
  count             = local.env == "dev" ? 1 : 0
  domain_name       = "app-internal-${local.env}.internal"
  validation_method = "DNS"
  tags              = merge(var.tags, { Environment = local.env })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_acm_certificate" "app_prod" {
  count             = local.env == "prod" ? 1 : 0
  domain_name       = "app-prod.example.com"
  validation_method = "DNS"
  tags              = merge(var.tags, { Environment = local.env })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_target_group" "app" {
  name        = "app-${local.env}"
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = data.aws_vpc.default.id
  target_type = "ip"
}
```

### `modules/app/outputs.tf`

```hcl
output "eks_cluster_name" {
  value = aws_eks_cluster.app.name
}

output "eks_cluster_endpoint" {
  value = aws_eks_cluster.app.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.app_assets.id
}

output "rds_endpoint" {
  value = aws_db_instance.app.endpoint
}

output "db_secret_arn" {
  value = aws_secretsmanager_secret.db_password.arn
}

output "service_role_arn" {
  value = aws_iam_role.app_service.arn
}

output "alb_dns" {
  value = try(aws_lb.app_internal[0].dns_name, null)
}

output "cloudfront_domain" {
  value = try(aws_cloudfront_distribution.app[0].domain_name, null)
}
```

---

## Phase 3: Update Root Config

### `main.tf`

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }

  backend "s3" {
    bucket         = "terraform-state-prod"
    key            = "app/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-lock"
  }
}

provider "aws" {
  region = var.aws_region
}

module "app" {
  for_each = toset(["dev", "prod"])

  source = "./modules/app"

  environment                       = each.value
  aws_region                        = var.aws_region_per_env[each.value]
  eks_node_count                    = var.eks_config[each.value].node_count
  eks_instance_type                 = var.eks_config[each.value].instance_type
  rds_instance_class                = var.rds_config[each.value].instance_class
  rds_multi_az                      = var.rds_config[each.value].multi_az
  s3_replication_enabled            = each.value == "prod"
  s3_replication_destination_region = "us-west-2"
  iam_oidc_enabled                  = each.value == "prod"
  oidc_provider_arn                 = each.value == "prod" ? var.oidc_provider_arn : null

  tags = {
    Project     = "app"
    Environment = each.value
    ManagedBy   = "Terraform"
  }
}
```

### `variables.tf`

```hcl
variable "aws_region_per_env" {
  type = map(string)
  default = {
    dev  = "us-east-1"
    prod = "us-east-1"
  }
}

variable "eks_config" {
  type = map(object({
    node_count    = number
    instance_type = string
  }))
  default = {
    dev = {
      node_count    = 2
      instance_type = "t3.medium"
    }
    prod = {
      node_count    = 4
      instance_type = "t3.large"
    }
  }
}

variable "rds_config" {
  type = map(object({
    instance_class = string
    multi_az       = bool
  }))
  default = {
    dev = {
      instance_class = "db.t3.micro"
      multi_az       = false
    }
    prod = {
      instance_class = "db.t3.medium"
      multi_az       = true
    }
  }
}

variable "oidc_provider_arn" {
  type        = string
  description = "OIDC provider ARN for prod EKS IRSA"
  default     = null
}
```

### `dev.tfvars`

```hcl
aws_region_per_env = {
  dev  = "us-east-1"
  prod = "us-east-1"
}

oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEID"
```

### `prod.tfvars`

```hcl
aws_region_per_env = {
  dev  = "us-east-1"
  prod = "us-east-1"
}

oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEID"
```

---

## Phase 4: Zero-Diff State Migration

### Step 1: Plan the refactor (expect changes in addresses, not resources)

```bash
terraform plan -out=tfplan.dev -var-file=dev.tfvars 2>&1 | head -50
```

You'll see **drift in resource addresses**, not actual resource recreation:
```
No changes. Resources are as before, but they will be moved.
```

### Step 2: Generate `state mv` commands

Before applying, manually execute state moves for each resource. Example for dev:

```bash
# EKS Cluster
terraform state mv aws_eks_cluster.dev module.app["dev"].aws_eks_cluster
terraform state mv aws_eks_node_group.dev module.app["dev"].aws_eks_node_group

# S3
terraform state mv aws_s3_bucket.dev module.app["dev"].aws_s3_bucket.app_assets
terraform state mv aws_s3_bucket_versioning.dev module.app["dev"].aws_s3_bucket_versioning.app_assets
terraform state mv aws_s3_bucket_server_side_encryption_configuration.dev module.app["dev"].aws_s3_bucket_server_side_encryption_configuration.app_assets
terraform state mv aws_s3_bucket_public_access_block.dev module.app["dev"].aws_s3_bucket_public_access_block.app_assets

# RDS
terraform state mv aws_db_instance.dev module.app["dev"].aws_db_instance.app
terraform state mv random_password.db_password_dev module.app["dev"].random_password.db_password
terraform state mv aws_secretsmanager_secret.db_password_dev module.app["dev"].aws_secretsmanager_secret.db_password
terraform state mv aws_secretsmanager_secret_version.db_password_dev module.app["dev"].aws_secretsmanager_secret_version.db_password

# IAM
terraform state mv aws_iam_role.app_service_dev module.app["dev"].aws_iam_role.app_service
terraform state mv aws_iam_role_policy.app_service_dev module.app["dev"].aws_iam_role_policy.app_service
terraform state mv aws_iam_user.app_service_dev module.app["dev"].aws_iam_user.app_service[0]
terraform state mv aws_iam_access_key.app_service_dev module.app["dev"].aws_iam_access_key.app_service[0]

# ALB
terraform state mv aws_lb.app_internal_dev module.app["dev"].aws_lb.app_internal[0]
terraform state mv aws_lb_listener.app_internal_dev module.app["dev"].aws_lb_listener.app_internal[0]
terraform state mv aws_acm_certificate.app_internal_dev module.app["dev"].aws_acm_certificate.app_internal[0]

# Supporting
terraform state mv aws_db_subnet_group.dev module.app["dev"].aws_db_subnet_group.app
terraform state mv aws_security_group.rds_dev module.app["dev"].aws_security_group.rds
terraform state mv aws_security_group.app_dev module.app["dev"].aws_security_group.app
terraform state mv aws_iam_role.eks_cluster_dev module.app["dev"].aws_iam_role.eks_cluster
terraform state mv aws_iam_role_policy_attachment.eks_cluster_policy_dev module.app["dev"].aws_iam_role_policy_attachment.eks_cluster_policy
